export type portalCompaniesGetResponse200 = {
  data: CompanyDto
  status: 200
}
    
export type portalCompaniesGetResponseSuccess = (portalCompaniesGetResponse200) & {
  headers: Headers;
};
;

export type portalCompaniesGetResponse = (portalCompaniesGetResponseSuccess)

export const getPortalCompaniesGetUrl = (id: string,) => {


  

  return `/v1/portal/companies/${id}`
}

export const portalCompaniesGet = async (id: string, options?: RequestInit): Promise<portalCompaniesGetResponse> => {
  
  const res = await fetch(getPortalCompaniesGetUrl(id),
  {      
    ...options,
    method: 'GET'
    
    
  }
)

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();
  
  const data: portalCompaniesGetResponse['data'] = body ? JSON.parse(body) : {}
  return { data, status: res.status, headers: res.headers } as portalCompaniesGetResponse
}



